// Extraire la traduction Claude
const input = $input.first().json;
const prevData = $('Loop Segments').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let claudeTranslation = '';
let claudeError = null;
let claudeUsage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

if (statusCode >= 400 || data.type === 'error' || data.error) {
  claudeError = data.error?.message || data.message || `Erreur Claude HTTP ${statusCode}`;
} else if (data.content?.[0]?.text) {
  claudeTranslation = data.content[0].text.trim();
  claudeUsage = {
    input_tokens: data.usage?.input_tokens || 0,
    output_tokens: data.usage?.output_tokens || 0,
    total_tokens: (data.usage?.input_tokens || 0) + (data.usage?.output_tokens || 0)
  };
}

return [{
  json: {
    ...prevData,
    claudeTranslation: claudeTranslation,
    claudeError: claudeError,
    claudeUsage: claudeUsage
  }
}];

// Extraire et combiner les résultats
const input = $input.first().json;
const prevData = $('Claude OK?').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let gptVerification = {
  my_translation: prevData.claudeTranslation,
  approved: true,
  confidence: 0.8,
  issues: []
};
let gptUsage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

if (statusCode < 400 && data.choices?.[0]?.message?.content) {
  try {
    gptVerification = JSON.parse(data.choices[0].message.content);
    gptUsage = {
      input_tokens: data.usage?.prompt_tokens || 0,
      output_tokens: data.usage?.completion_tokens || 0,
      total_tokens: (data.usage?.prompt_tokens || 0) + (data.usage?.completion_tokens || 0)
    };
  } catch (e) {
    // Garder les valeurs par défaut
  }
}

// Déterminer la traduction finale
const finalTranslation = gptVerification.approved ? prevData.claudeTranslation : (gptVerification.my_translation || prevData.claudeTranslation);

return [{
  json: {
    ...prevData,
    gptVerification: gptVerification,
    gptUsage: gptUsage,
    finalTranslation: finalTranslation,
    confidence: gptVerification.confidence || 0.8,
    approved: gptVerification.approved
  }
}];

// Préparer les données pour la mise à jour
const input = $input.first().json;
const prevData = $('Extract GPT').first().json;

const segmentIndex = prevData.segmentIndex;
const totalSegments = prevData.totalSegments;
const isComplete = segmentIndex + 1 >= totalSegments;

// Récupérer les tokens Claude et GPT
const claudeUsage = prevData.claudeUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
const gptUsage = prevData.gptUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

// Construire l objet tokens avec détail par provider
const tokens = {
  claude: {
    input_tokens: claudeUsage.input_tokens || 0,
    output_tokens: claudeUsage.output_tokens || 0,
    total_tokens: claudeUsage.total_tokens || 0
  },
  gpt: {
    input_tokens: gptUsage.input_tokens || 0,
    output_tokens: gptUsage.output_tokens || 0,
    total_tokens: gptUsage.total_tokens || 0
  },
  total: {
    input_tokens: (claudeUsage.input_tokens || 0) + (gptUsage.input_tokens || 0),
    output_tokens: (claudeUsage.output_tokens || 0) + (gptUsage.output_tokens || 0),
    total_tokens: (claudeUsage.total_tokens || 0) + (gptUsage.total_tokens || 0)
  }
};

// Calculer le pourcentage de progression
const current = segmentIndex + 1;
const percentage = Math.round((current / totalSegments) * 100);

return [{
  json: {
    ...prevData,
    isComplete: isComplete,
    updatePayload: isComplete ? {
      status: 'completed',
      progress: {
        current: current,
        total: totalSegments,
        percentage: 100,
        step: 'completed'
      },
      output: {
        translations_saved: current,
        tokens: tokens
      }
    } : {
      status: 'processing',
      progress: {
        current: current,
        total: totalSegments,
        percentage: percentage,
        step: 'translating'
      },
      output: {
        current_segment_text: prevData.segmentText.substring(0, 100),
        translations_saved: current,
        tokens: tokens
      }
    }
  }
}];

// Préparer la mise à jour pour erreur
const input = $input.first().json;

const segmentIndex = input.segmentIndex;
const totalSegments = input.totalSegments;
const isComplete = segmentIndex + 1 >= totalSegments;
const current = segmentIndex + 1;
const percentage = Math.round((current / totalSegments) * 100);

return [{
  json: {
    ...input,
    isComplete: isComplete,
    updatePayload: isComplete ? {
      status: 'completed',
      progress: {
        current: current,
        total: totalSegments,
        percentage: 100,
        step: 'completed_with_errors'
      },
      output: {
        translations_saved: segmentIndex,
        error: input.claudeError || 'Translation failed'
      }
    } : {
      status: 'processing',
      progress: {
        current: current,
        total: totalSegments,
        percentage: percentage,
        step: 'error_recovery'
      },
      output: {
        translations_saved: segmentIndex,
        error: input.claudeError || 'Translation failed'
      }
    }
  }
}];
